import{_ as d,o as e,c as a,ak as r}from"./chunks/framework.BNVJvTzl.js";const p=JSON.parse('{"title":"Who can do what","description":"Who can do what in VERA: every feature against every role, from team member to owner, in one set of tables.","frontmatter":{"description":"Who can do what in VERA: every feature against every role, from team member to owner, in one set of tables."},"headers":[],"relativePath":"guide/who-can-do-what.md","filePath":"guide/who-can-do-what.md"}'),o={name:"guide/who-can-do-what.md"};function n(i,t,s,h,c,l){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="who-can-do-what" tabindex="-1">Who can do what <a class="header-anchor" href="#who-can-do-what" aria-label="Permalink to &quot;Who can do what&quot;">​</a></h1><p>One page to check what each role can do in VERA. Each table covers one area. A ✅ means yes, a ❌ means no, and a note means &quot;yes, but only in this case&quot;.</p><p><strong>The columns:</strong></p><ul><li><strong>Team member</strong> records and reviews their own time.</li><li><strong>Manager</strong> runs projects. Most of what a manager can do on a project depends on whether they are its PM.</li><li><strong>Project&#39;s PM</strong> is a manager who is the PM of that project. This column shows what they can do on that project only.</li><li><strong>Manager Plus</strong> is a manager who can also see and manage money. A Manager Plus who is a project&#39;s PM can also do everything in the Project&#39;s PM column on that project.</li><li><strong>Owner &amp; Admin</strong> can do everything. The only difference between the two: admins are left out of capacity, utilization and team totals.</li></ul><p>Vendors can&#39;t sign in to VERA. In Slack, everyone can only record, see and edit their own time.</p><h2 id="recording-time" tabindex="-1">Recording time <a class="header-anchor" href="#recording-time" aria-label="Permalink to &quot;Recording time&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>Record your own time</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Record time for someone else</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>See and edit your own time</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Move your own time to another project</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Delete your own time</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>See everyone&#39;s time</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Edit someone else&#39;s time</td><td>❌</td><td>❌</td><td>On that project</td><td>✅</td><td>✅</td></tr><tr><td>Move someone else&#39;s time to another project</td><td>❌</td><td>❌</td><td>Between projects they manage</td><td>✅</td><td>✅</td></tr><tr><td>Delete someone else&#39;s time</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Approve T&amp;M time for billing</td><td>❌</td><td>❌</td><td>✅</td><td>❌</td><td>✅</td></tr></tbody></table><p>Nobody records time for anyone else: each person records their own. Time on an issued or paid invoice can&#39;t be edited, moved or deleted by anyone until the invoice is voided. Time is never moved into or out of PTO, Sick or Leave.</p><h2 id="time-off" tabindex="-1">Time off <a class="header-anchor" href="#time-off" aria-label="Permalink to &quot;Time off&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>Request time off</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Approve or reject time off</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Record a sick day or leave for someone else</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>See everyone&#39;s upcoming time off</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Record a vendor&#39;s time away</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>See company holidays</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Add or remove company holidays</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr></tbody></table><p>An owner&#39;s own time off is approved at once.</p><h2 id="projects-and-clients" tabindex="-1">Projects and clients <a class="header-anchor" href="#projects-and-clients" aria-label="Permalink to &quot;Projects and clients&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>Open a project&#39;s page</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Create a project or a client</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Choose a project&#39;s PM</td><td>❌</td><td>Themselves, if it has none</td><td>Hand it to another manager</td><td>Themselves, if it has none</td><td>✅</td></tr><tr><td>Rename a project</td><td>❌</td><td>❌</td><td>✅</td><td>❌</td><td>✅</td></tr><tr><td>Change its deadline, start date or hours budget</td><td>❌</td><td>❌</td><td>✅</td><td>❌</td><td>✅</td></tr><tr><td>Turn tasks on or off for a project</td><td>❌</td><td>❌</td><td>✅</td><td>❌</td><td>✅</td></tr><tr><td>Set contract value, billing rate, target LER or billing schedule</td><td>❌</td><td>When creating it</td><td>When creating it</td><td>✅</td><td>✅</td></tr><tr><td>Change a project&#39;s type, duplicate it or merge it</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Move a project to another client</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Close, cancel or delete a project</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Re-up a retainer or edit an open period</td><td>❌</td><td>❌</td><td>Hours and dates</td><td>✅</td><td>✅</td></tr><tr><td>Edit a closed retainer period</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Rename, archive or delete a client</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr></tbody></table><h2 id="allocations-and-capacity" tabindex="-1">Allocations and capacity <a class="header-anchor" href="#allocations-and-capacity" aria-label="Permalink to &quot;Allocations and capacity&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>See your own allocations</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Add, edit, shape or cancel allocations</td><td>❌</td><td>Not on a retainer&#39;s periods</td><td>✅</td><td>Not on a retainer&#39;s periods</td><td>✅</td></tr><tr><td>See capacity</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>See monthly hours by project and person</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Resolve items in Needs you</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table><h2 id="vendors-and-fixed-fees" tabindex="-1">Vendors and fixed fees <a class="header-anchor" href="#vendors-and-fixed-fees" aria-label="Permalink to &quot;Vendors and fixed fees&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>See a project&#39;s fixed fees</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Add or cancel a fixed fee</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Edit a fixed fee</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr></tbody></table><h2 id="money" tabindex="-1">Money <a class="header-anchor" href="#money" aria-label="Permalink to &quot;Money&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>See a project&#39;s LER</td><td>❌</td><td>❌</td><td>The ratio only</td><td>✅</td><td>✅</td></tr><tr><td>See revenue, cost and margin</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Use the Money and Performance pages</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Download time entries as a spreadsheet</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>See people&#39;s cost rates</td><td>❌</td><td>❌</td><td>❌</td><td>Read only</td><td>✅</td></tr><tr><td>Set cost rates and salary bands</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr></tbody></table><p>Managers never see what people are paid.</p><h2 id="invoices-proposals-and-the-ai-connector" tabindex="-1">Invoices, proposals and the AI connector <a class="header-anchor" href="#invoices-proposals-and-the-ai-connector" aria-label="Permalink to &quot;Invoices, proposals and the AI connector&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>Create, issue and download invoices</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Record payments on an invoice</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Set your invoicing details and clients&#39; billing details</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Create and price proposals</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Connect an AI assistant to VERA</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Turn the AI connector on or off</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr></tbody></table><h2 id="people-and-settings" tabindex="-1">People and settings <a class="header-anchor" href="#people-and-settings" aria-label="Permalink to &quot;People and settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Team member</th><th>Manager</th><th>Project&#39;s PM</th><th>Manager Plus</th><th>Owner &amp; Admin</th></tr></thead><tbody><tr><td>Add people, change roles, deactivate people</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Send someone an invite to sign in</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Change workspace settings, tasks and disciplines</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Import from Harvest</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>See the logs</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Subscribe and manage billing</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Switch your own account between Owner and Admin</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Turn on privacy mode</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>Admins only</td></tr></tbody></table><p>For more detail on each role, see <a href="./roles.html">Your role in VERA</a>.</p>',25)])])}const b=d(o,[["render",n]]);export{p as __pageData,b as default};
